#include <bits/stdc++.h>
using namespace std;

// Persistent segment tree over compressed keys; a leaf holds a value id (0 = absent).
vector<uint32_t> L{0}, R{0}, V{0};
int width;

uint32_t update(uint32_t node, int lo, int hi, int index, uint32_t v) {
    uint32_t cur = L.size();
    L.push_back(L[node]);
    R.push_back(R[node]);
    V.push_back(V[node]);
    if (hi - lo == 1) {
        V[cur] = v;
    } else {
        int mid = (lo + hi) / 2;
        if (index < mid) {
            uint32_t child = update(L[node], lo, mid, index, v);
            L[cur] = child;
        } else {
            uint32_t child = update(R[node], mid, hi, index, v);
            R[cur] = child;
        }
    }
    return cur;
}

uint32_t lookup(uint32_t node, int index) {
    int lo = 0, hi = width;
    while (node && hi - lo > 1) {
        int mid = (lo + hi) / 2;
        if (index < mid) node = L[node], hi = mid;
        else node = R[node], lo = mid;
    }
    return V[node];
}

int main() {
    string data;
    char buf[1 << 16];
    for (size_t got; (got = fread(buf, 1, sizeof buf, stdin)) > 0;) data.append(buf, got);
    vector<string_view> tok;
    auto space = [](char c) { return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == '\v' || c == '\f'; };
    for (size_t i = 0; i < data.size();) {
        while (i < data.size() && space(data[i])) i++;
        size_t j = i;
        while (j < data.size() && !space(data[j])) j++;
        if (j > i) tok.emplace_back(data.data() + i, j - i);
        i = j;
    }
    int n = stoi(string(tok[0]));
    // First pass: collect every key for offline compression.
    unordered_map<string_view, int> ids;
    ids.reserve(n);
    size_t pos = 1;
    for (int k = 0; k < n; k++) {
        string_view c = tok[pos++];
        int size = c == "SET" ? 2 : c == "BACKUP" ? 0 : 1;
        if (c == "SET" || c == "GET" || c == "DELETE") ids.emplace(tok[pos], (int)ids.size());
        pos += size;
    }
    width = max<int>(1, ids.size());
    vector<string_view> values{"NULL"};
    vector<uint32_t> saved{0};
    uint32_t root = 0;
    string out;
    pos = 1;
    for (int k = 0; k < n; k++) {
        string_view c = tok[pos++];
        if (c == "SET") {
            int key = ids[tok[pos]];
            values.push_back(tok[pos + 1]);
            pos += 2;
            root = update(root, 0, width, key, values.size() - 1);
            out += "OK\n";
        } else if (c == "GET") {
            out += values[lookup(root, ids[tok[pos++]])];
            out += '\n';
        } else if (c == "DELETE") {
            int key = ids[tok[pos++]];
            if (lookup(root, key)) {
                root = update(root, 0, width, key, 0);
                out += "OK\n";
            } else {
                out += "NULL\n";
            }
        } else if (c == "BACKUP") {
            saved.push_back(root);
            out += to_string(saved.size() - 1);
            out += '\n';
        } else {  // RESTORE
            long long v = stoll(string(tok[pos++]));
            if (v >= 1 && v < (long long)saved.size()) {
                root = saved[v];
                out += "OK\n";
            } else {
                out += "NULL\n";
            }
        }
    }
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    // Persistent segment tree over compressed keys; a leaf holds a value id (0 = absent).
    static int[] L = new int[1 << 20], R = new int[1 << 20], V = new int[1 << 20];
    static int size = 1, width;

    static int newNode(int from) {
        if (size == L.length) {
            L = Arrays.copyOf(L, size * 2);
            R = Arrays.copyOf(R, size * 2);
            V = Arrays.copyOf(V, size * 2);
        }
        L[size] = L[from];
        R[size] = R[from];
        V[size] = V[from];
        return size++;
    }

    static int update(int node, int lo, int hi, int index, int v) {
        int cur = newNode(node);
        if (hi - lo == 1) {
            V[cur] = v;
        } else {
            int mid = (lo + hi) / 2;
            if (index < mid) {
                int child = update(L[node], lo, mid, index, v);
                L[cur] = child;
            } else {
                int child = update(R[node], mid, hi, index, v);
                R[cur] = child;
            }
        }
        return cur;
    }

    static int lookup(int node, int index) {
        int lo = 0, hi = width;
        while (node != 0 && hi - lo > 1) {
            int mid = (lo + hi) / 2;
            if (index < mid) { node = L[node]; hi = mid; }
            else { node = R[node]; lo = mid; }
        }
        return V[node];
    }

    public static void main(String[] args) throws IOException {
        // ISO-8859-1 maps bytes 1:1, so UTF-8 keys and values round-trip unchanged.
        String data = new String(System.in.readAllBytes(), StandardCharsets.ISO_8859_1);
        StringTokenizer st = new StringTokenizer(data, " \n\r\t\u000b\f");
        int n = Integer.parseInt(st.nextToken());
        String[] cmd = new String[n], a = new String[n], b = new String[n];
        // First pass: collect every key for offline compression.
        HashMap<String, Integer> ids = new HashMap<>();
        for (int k = 0; k < n; k++) {
            String c = st.nextToken();
            cmd[k] = c;
            if (!c.equals("BACKUP")) a[k] = st.nextToken();
            if (c.equals("SET")) b[k] = st.nextToken();
            if (c.equals("SET") || c.equals("GET") || c.equals("DELETE")) ids.putIfAbsent(a[k], ids.size());
        }
        width = Math.max(1, ids.size());
        ArrayList<String> values = new ArrayList<>();
        values.add("NULL");
        ArrayList<Integer> saved = new ArrayList<>();
        saved.add(0);
        int root = 0;
        StringBuilder out = new StringBuilder();
        for (int k = 0; k < n; k++) {
            String c = cmd[k];
            if (c.equals("SET")) {
                values.add(b[k]);
                root = update(root, 0, width, ids.get(a[k]), values.size() - 1);
                out.append("OK\n");
            } else if (c.equals("GET")) {
                out.append(values.get(lookup(root, ids.get(a[k])))).append('\n');
            } else if (c.equals("DELETE")) {
                int key = ids.get(a[k]);
                if (lookup(root, key) != 0) {
                    root = update(root, 0, width, key, 0);
                    out.append("OK\n");
                } else {
                    out.append("NULL\n");
                }
            } else if (c.equals("BACKUP")) {
                saved.add(root);
                out.append(saved.size() - 1).append('\n');
            } else { // RESTORE
                long v = Long.parseLong(a[k]);
                if (v >= 1 && v < saved.size()) {
                    root = saved.get((int) v);
                    out.append("OK\n");
                } else {
                    out.append("NULL\n");
                }
            }
        }
        System.out.write(out.toString().getBytes(StandardCharsets.ISO_8859_1));
        System.out.flush();
    }
}

