import (
	"bufio"
	"io"
	"os"
	"strconv"
)

// Persistent segment tree over compressed keys; a leaf holds a value id (0 = absent).
var L, R, V = []uint32{0}, []uint32{0}, []uint32{0}
var width int

func update(node uint32, lo, hi, index int, v uint32) uint32 {
	cur := uint32(len(L))
	L = append(L, L[node])
	R = append(R, R[node])
	V = append(V, V[node])
	if hi-lo == 1 {
		V[cur] = v
	} else {
		mid := (lo + hi) / 2
		if index < mid {
			child := update(L[node], lo, mid, index, v)
			L[cur] = child
		} else {
			child := update(R[node], mid, hi, index, v)
			R[cur] = child
		}
	}
	return cur
}

func lookup(node uint32, index int) uint32 {
	lo, hi := 0, width
	for node != 0 && hi-lo > 1 {
		mid := (lo + hi) / 2
		if index < mid {
			node, hi = L[node], mid
		} else {
			node, lo = R[node], mid
		}
	}
	return V[node]
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	var tok []string
	space := func(c byte) bool { return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == '\v' || c == '\f' }
	for i := 0; i < len(data); {
		for i < len(data) && space(data[i]) {
			i++
		}
		j := i
		for j < len(data) && !space(data[j]) {
			j++
		}
		if j > i {
			tok = append(tok, string(data[i:j]))
		}
		i = j
	}
	n, _ := strconv.Atoi(tok[0])
	// First pass: collect every key for offline compression.
	ids := make(map[string]int, n)
	pos := 1
	for k := 0; k < n; k++ {
		c := tok[pos]
		pos++
		if c == "SET" || c == "GET" || c == "DELETE" {
			if _, ok := ids[tok[pos]]; !ok {
				ids[tok[pos]] = len(ids)
			}
		}
		switch c {
		case "SET":
			pos += 2
		case "BACKUP":
		default:
			pos++
		}
	}
	width = max(1, len(ids))
	values := []string{"NULL"}
	saved := []uint32{0}
	var root uint32
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	pos = 1
	for k := 0; k < n; k++ {
		c := tok[pos]
		pos++
		switch c {
		case "SET":
			values = append(values, tok[pos+1])
			root = update(root, 0, width, ids[tok[pos]], uint32(len(values)-1))
			pos += 2
			w.WriteString("OK\n")
		case "GET":
			w.WriteString(values[lookup(root, ids[tok[pos]])])
			w.WriteByte('\n')
			pos++
		case "DELETE":
			key := ids[tok[pos]]
			pos++
			if lookup(root, key) != 0 {
				root = update(root, 0, width, key, 0)
				w.WriteString("OK\n")
			} else {
				w.WriteString("NULL\n")
			}
		case "BACKUP":
			saved = append(saved, root)
			w.WriteString(strconv.Itoa(len(saved) - 1))
			w.WriteByte('\n')
		default: // RESTORE
			v, _ := strconv.ParseInt(tok[pos], 10, 64)
			pos++
			if v >= 1 && v < int64(len(saved)) {
				root = saved[v]
				w.WriteString("OK\n")
			} else {
				w.WriteString("NULL\n")
			}
		}
	}
}
